insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_breathtaking_5','breathtaking','adjective','so beautiful or impressive that it makes people stop and stare in amazement','[{"senseId":"breathtaking_5_1","meaning":"so beautiful or impressive that it makes people stop and stare in amazement","acceptedParaphrases":["awe-inspiring","astonishingly beautiful"],"masteryContexts":[{"contextId":"u5_11_breathtaking_5_meaning","text":"The tour guide waited at the viewpoint so that the group could take in the breathtaking sight of the sun rising over the temple.","meaning":"so beautiful or impressive that it amazes you","wrongMeanings":["so quiet and empty that nobody visits it","so old and fragile that nobody may touch it","so cold and wet that nobody enjoys it"]},{"contextId":"u5_11_breathtaking_5_paraphrase","text":"The helicopter ride over the canyon was a breathtaking experience, and the whole group fell silent as the cliffs rose around us.","meaning":"so exciting and impressive that it leaves you amazed","wrongMeanings":["so long and tiring that you never forget it","so dangerous and risky that you never forget it","so expensive and rare that you never forget it"]}],"situationDistractors":["The tour group sat in a café and complained that a bus was blocking the window.","The hotel lobby was plain and quiet, and the guests waited patiently for their keys.","The visitors walked quickly past the monument, glanced at it and returned to the coach.","The package holiday included a free shuttle to the airport and a cooked breakfast each morning.","The tour leader checked everyone’s passports before the group went through customs.","Heavy traffic on the ring road made the coach forty minutes late for the lunch stop."],"gapDistractors":[{"contextId":"u5_11_breathtaking_5_gap_1","answer":"breathtaking","wrong":["routine","familiar","tedious"]},{"contextId":"u5_11_breathtaking_5_gap_2","answer":"breathtaking","wrong":["ordinary","tiresome","harmless"]},{"contextId":"u5_11_breathtaking_5_gap_3","answer":"breathtaking","wrong":["routine","quiet","faded"]}],"spellingErrors":["brethtaking","breathtakeing","breathtaiking","breathtacking","breaththaking","breathaking"],"masteryPassages":[{"passageId":"u5_11_breathtaking_5_passage_1","contextId":"u5_11_breathtaking_5_gap_1","text":"The coach stopped at a high viewpoint above the fjord. Everyone stepped out in silence, because the scene below was so ____ that nobody could find the words to describe it.","answer":"breathtaking"},{"passageId":"u5_11_breathtaking_5_passage_2","contextId":"u5_11_breathtaking_5_gap_2","text":"Skydiving over the coast was frightening and thrilling at the same time. Later, the passengers agreed that the ____ views of the shoreline were worth every moment of fear.","answer":"breathtaking"}],"contextDependentParaphrases":[],"wrongParaphrases":["peaceful","crowded","ordinary"],"misleadingDistractors":["hard to breathe in because the air is thin","extremely cold, with strong winds","so crowded that people cannot move"],"teacherNote":"Unit 5 item (breathtaking_5): the tourism sense of amazement at a sight. Unit 4 vocab_breathtaking is a separate item that shares only the lexical spelling list."}]'::jsonb,'[]'::jsonb,'["breathtaking sunrise","truly breathtaking","breathtaking experience"]'::jsonb,'live'),
('vocab_spectacular','spectacular','adjective','very impressive, striking and exciting to look at, often because of its size or scale','[{"senseId":"spectacular_1","meaning":"very impressive, striking and exciting to look at, often because of its size or scale","acceptedParaphrases":["grand and striking","impressive on a large scale"],"masteryContexts":[{"contextId":"u5_12_spectacular_meaning","text":"Victoria Falls is spectacular, especially in the rainy season, when millions of litres of water crash into the gorge every second.","meaning":"very impressive to look at, especially because of its size and power","wrongMeanings":["very dangerous to visit, especially because of its depth and speed","very popular with visitors, especially because of its size and price","very old and famous, especially because of its history and name"]},{"contextId":"u5_12_spectacular_paraphrase","text":"The ice hotel puts on a spectacular show of light and music every winter evening.","meaning":"exciting and impressive to watch, on a grand scale","wrongMeanings":["frightening and risky to watch, with great danger","quiet and relaxing to watch, with soft music","cheap and simple to watch, with a small crowd"]}],"situationDistractors":["A small café on the corner served tea and sandwiches to the walkers.","The bus arrived at the hotel, and the driver unloaded the bags in the rain.","The tourists spent a quiet evening reading in the lounge.","The campsite shop sold bottled water, matches and postcards of the village.","A queue of cars waited at the toll booth while the driver counted out the coins.","The hotel porter carried the heavy cases up two flights of stairs."],"gapDistractors":[{"contextId":"u5_12_spectacular_gap_1","answer":"spectacular","wrong":["modest","quiet","routine"]},{"contextId":"u5_12_spectacular_gap_2","answer":"spectacular","wrong":["modest","gentle","tiny"]},{"contextId":"u5_12_spectacular_gap_3","answer":"spectacular","wrong":["hidden","tiny","faint"]}],"spellingErrors":["spectaculer","spectakular","spectaclar","spectacualr","spectaculor","spectacullar"],"wordFamilyForms":[{"form":"spectacular","partOfSpeech":"adjective","example":"The view from the cable car was spectacular, with glaciers on both sides.","pedagogicallyUseful":true},{"form":"spectacle","partOfSpeech":"noun","example":"The fireworks over the harbour were a magnificent spectacle.","pedagogicallyUseful":true,"altExample":"Thousands of tourists gather each winter to watch the spectacle of the northern lights."},{"form":"spectacularly","partOfSpeech":"adverb","example":"The waterfall plunges spectacularly into the gorge after the spring rains.","pedagogicallyUseful":true,"altExample":"The sunset turned the whole lagoon spectacularly red."}],"masteryPassages":[{"passageId":"u5_12_spectacular_passage_1","contextId":"u5_12_spectacular_gap_1","text":"The festival organisers wanted something unforgettable for the final night. They launched thousands of lanterns into the sky, and the ____ display could be seen from every hotel along the beach.","answer":"spectacular"},{"passageId":"u5_12_spectacular_passage_2","contextId":"u5_12_spectacular_gap_2","text":"The volcano erupts every few weeks, and boat trips take visitors close enough to watch. From the deck, passengers see ____ fountains of red lava shooting hundreds of metres into the air.","answer":"spectacular"}],"contextDependentParaphrases":[],"wrongParaphrases":["large and heavy","bright and noisy","tall and narrow"],"misleadingDistractors":["causing great fear or danger to those who watch","popular with large numbers of tourists","very expensive for ordinary visitors"]}]'::jsonb,'["spectacle","spectacularly"]'::jsonb,'["spectacular show","spectacular waterfall","absolutely spectacular"]'::jsonb,'live'),
('vocab_dramatic','dramatic','adjective','very noticeable and powerful, because of sharp contrasts or sudden changes','[{"senseId":"dramatic_1","meaning":"very noticeable and powerful, because of sharp contrasts or sudden changes","acceptedParaphrases":["striking and powerful","sudden and sharp"],"masteryContexts":[{"contextId":"u5_13_dramatic_meaning","text":"The road climbs through dramatic mountain scenery, with sharp peaks, deep valleys and clouds that change colour every hour.","meaning":"striking and powerful, with strong contrasts","wrongMeanings":["calm and gentle, with soft colours","crowded and noisy, with busy roads","neat and tidy, with straight lines"]},{"contextId":"u5_13_dramatic_paraphrase","text":"There has been a dramatic rise in the number of tourists visiting the island since the new airport opened.","meaning":"sudden and very large","wrongMeanings":["slow and very small","steady and very regular","rare and very expensive"]}],"situationDistractors":["The path followed a gentle river through flat fields, and nothing changed along the way.","The number of visitors stayed almost the same from one year to the next.","The weather was mild and cloudy all week, with no wind and no rain.","The hostel offers free tea and toast between seven and nine each morning.","The language school arranged a short walking tour of the town for new arrivals.","Tourists lined up at the kiosk to buy tickets for the afternoon boat."],"gapDistractors":[{"contextId":"u5_13_dramatic_gap_1","answer":"dramatic","wrong":["plain","pale","cloudless"]},{"contextId":"u5_13_dramatic_gap_2","answer":"dramatic","wrong":["slight","gradual","minor"]},{"contextId":"u5_13_dramatic_gap_3","answer":"dramatic","wrong":["quiet","dull","slow"]}],"spellingErrors":["dramatik","dramatc","dramatick","dramtic","drammatic","dramaticc"],"masteryPassages":[{"passageId":"u5_13_dramatic_passage_1","contextId":"u5_13_dramatic_gap_1","text":"In the morning, the valley was calm and green. By afternoon the weather had turned: black clouds rolled in, the wind roared and lightning lit the peaks, creating a ____ scene that the photographers rushed to capture.","answer":"dramatic"},{"passageId":"u5_13_dramatic_passage_2","contextId":"u5_13_dramatic_gap_2","text":"Tourism on the island used to be very small. Since the airport opened, however, the figures have shown a ____ rise, and the number of hotels has tripled in five years.","answer":"dramatic"}],"contextDependentParaphrases":[],"wrongParaphrases":["bright and cheerful","tall and narrow","old and traditional"],"misleadingDistractors":["connected with acting and the theatre","calm, gentle and easy to relax in","popular with large crowds of visitors"]}]'::jsonb,'[]'::jsonb,'["dramatic change","dramatic landscape","dramatic increase"]'::jsonb,'live'),
('vocab_stunning','stunning','adjective','extremely attractive or beautiful, in a way that impresses you immediately','[{"senseId":"stunning_1","meaning":"extremely attractive or beautiful, in a way that impresses you immediately","acceptedParaphrases":["extremely attractive","strikingly beautiful"],"masteryContexts":[{"contextId":"u5_14_stunning_meaning","text":"The villa has a stunning terrace overlooking the bay, with white stone floors and a pool the colour of the sky.","meaning":"extremely attractive and impressive to look at","wrongMeanings":["very large and expensive to hire","very quiet and private to stay in","very old and traditional to see"]},{"contextId":"u5_14_stunning_paraphrase","text":"The island’s beaches are so stunning that they appear on the cover of almost every travel brochure.","meaning":"extremely beautiful and impressive to look at","wrongMeanings":["so shocking that they frighten people","so crowded that they stay in the memory","so remote that few people ever see them"]}],"situationDistractors":["The beach was littered with rubbish, and the sea smelt of oil.","The hotel room was small and dark, with a window that faced a brick wall.","The road to the village was muddy and full of holes.","The tour office was closed on Sundays, so the family planned their trip for Monday.","The coach driver stopped at the border while an officer checked the documents.","The guest asked the receptionist to recommend a good place for lunch."],"gapDistractors":[{"contextId":"u5_14_stunning_gap_1","answer":"stunning","wrong":["muddy","polluted","dull"]},{"contextId":"u5_14_stunning_gap_2","answer":"stunning","wrong":["faint","blurry","ordinary"]},{"contextId":"u5_14_stunning_gap_3","answer":"stunning","wrong":["gloomy","plain","dull"]}],"spellingErrors":["stuning","stunnin","stunnig","stunnng","stuuning","stunneng"],"masteryPassages":[{"passageId":"u5_14_stunning_passage_1","contextId":"u5_14_stunning_gap_1","text":"We checked into a tiny guesthouse on the cliff, and the room itself was simple. The real surprise was the balcony, which offered a ____ view of the bay, pink in the evening light.","answer":"stunning"},{"passageId":"u5_14_stunning_passage_2","contextId":"u5_14_stunning_gap_2","text":"The tourism poster showed a family on a golden beach under a pink sky. Everyone who saw it agreed that the picture was ____, and bookings doubled within a week.","answer":"stunning"}],"contextDependentParaphrases":[],"wrongParaphrases":["very expensive","very crowded","very peaceful"],"misleadingDistractors":["causing someone to lose consciousness","extremely shocking or upsetting to see","very large, tall and heavy"]}]'::jsonb,'[]'::jsonb,'["stunning beach","stunning backdrop","look stunning"]'::jsonb,'live'),
('vocab_popular','popular','adjective','liked or enjoyed by a large number of people','[{"senseId":"popular_1","meaning":"liked or enjoyed by a large number of people","acceptedParaphrases":["well-liked","favoured by many people"],"masteryContexts":[{"contextId":"u5_15_popular_meaning","text":"Cycling holidays have become very popular, and many hotels now offer secure places to keep bicycles.","meaning":"liked by many people","wrongMeanings":["known by very few people","needed by many people","paid for by many people"]},{"contextId":"u5_15_popular_paraphrase","text":"The restaurant on the harbour is popular with both locals and tourists, so booking a table is essential.","meaning":"enjoyed by large numbers of people","wrongMeanings":["avoided by large numbers of people","owned by large numbers of people","visited by nobody except local people"]}],"situationDistractors":["The little museum was almost empty, and the guide had no one to talk to all afternoon.","The visitors had to ask three people before anyone knew where the old castle was.","The restaurant on the corner closed down after only two months.","A heavy suitcase burst open on the conveyor belt, and the airline staff helped to repack it.","The guide handed each visitor a headset and a small leaflet at the entrance.","The campers pitched their tents beside the stream before dark."],"gapDistractors":[{"contextId":"u5_15_popular_gap_1","answer":"popular","wrong":["quiet","empty","unknown"]},{"contextId":"u5_15_popular_gap_2","answer":"popular","wrong":["friendly","angry","familiar"]},{"contextId":"u5_15_popular_gap_3","answer":"popular","wrong":["dangerous","expensive","difficult"]}],"spellingErrors":["populer","poplar","popullar","populaar","pupular","popuular"],"wordFamilyForms":[{"form":"popular","partOfSpeech":"adjective","example":"The coastal railway is popular with tourists and commuters alike.","pedagogicallyUseful":true},{"form":"popularity","partOfSpeech":"noun","example":"The popularity of the island has grown since the film was released.","pedagogicallyUseful":true,"altExample":"Cheap flights have increased the popularity of weekend breaks in Europe."},{"form":"unpopular","partOfSpeech":"adjective","example":"The new tourist tax proved unpopular with hotel owners.","pedagogicallyUseful":true,"altExample":"Long queues made the museum unpopular with school groups."}],"masteryPassages":[{"passageId":"u5_15_popular_passage_1","contextId":"u5_15_popular_gap_1","text":"The old market was almost empty when the tour company first added it to its programme. Now it is extremely ____, and visitors often wait twenty minutes to get in.","answer":"popular"},{"passageId":"u5_15_popular_passage_2","contextId":"u5_15_popular_gap_2","text":"The ferry company has added extra boats this year. Travel guides say that the harbour restaurants are the most ____ places to eat in town, because tourists and local people fill every table every evening.","answer":"popular"}],"contextDependentParaphrases":[],"wrongParaphrases":["crowded","expensive","unusual"],"misleadingDistractors":["known only to a small number of experts","available at a very low price","suitable for people of all ages"]}]'::jsonb,'["popularity","unpopular"]'::jsonb,'["popular destination","popular with tourists","increasingly popular"]'::jsonb,'live'),
('vocab_static','static','adjective','staying in one place or position, without moving or changing','[{"senseId":"static_1","meaning":"staying in one place or position, without moving or changing","acceptedParaphrases":["fixed","motionless"],"masteryContexts":[{"contextId":"u5_16_static_meaning","text":"Wildlife photographers often use a static camera hidden in a tree, which films the same waterhole for weeks.","meaning":"staying in one fixed position and not moving","wrongMeanings":["moving slowly from tree to tree","pointing in a different direction each hour","following animals through the forest"]},{"contextId":"u5_16_static_paraphrase","text":"Visitor numbers to the museum have remained static for three years, at about forty thousand a year.","meaning":"not changing or developing","wrongMeanings":["not paid for or counted","not ready or available","not seen or heard"]}],"situationDistractors":["The drone swooped over the beach, tilted and followed a surfer along the waves.","Prices at the hotel rose twice in the same year, and visitors complained.","The bus raced along the coast road, and the passengers were thrown from side to side.","The holiday rep gave a short talk about the week’s excursions at nine o’clock.","The family shared a taxi from the airport to the guesthouse.","Guests were asked to leave their keys at reception before going out for the day."],"gapDistractors":[{"contextId":"u5_16_static_gap_1","answer":"static","wrong":["wireless","portable","waterproof"]},{"contextId":"u5_16_static_gap_2","answer":"static","wrong":["erratic","unstable","seasonal"]},{"contextId":"u5_16_static_gap_3","answer":"static","wrong":["touring","mobile","folding"]}],"spellingErrors":["statick","staic","statik","statc","stattic","staticc"],"masteryPassages":[{"passageId":"u5_16_static_passage_1","contextId":"u5_16_static_gap_1","text":"Most travel programmes follow the presenter as she walks through the market. In one episode, however, the director used a ____ shot of the busy square from a window, and viewers watched the crowds move around the same still frame.","answer":"static"},{"passageId":"u5_16_static_passage_2","contextId":"u5_16_static_gap_2","text":"Local officials hoped that the new airport would increase tourism. Five years later, however, the figures were ____: roughly the same number of visitors arrived every summer, and neither hotels nor shops had grown.","answer":"static"}],"contextDependentParaphrases":[],"wrongParaphrases":["fragile","flexible","rapid"],"misleadingDistractors":["carrying a small electric charge","moving smoothly from one place to another","changing quickly in size and shape"]}]'::jsonb,'[]'::jsonb,'["static camera","static image","remain static"]'::jsonb,'live'),
('vocab_ground_level','ground-level','adjective','at or near the level of the ground, rather than high above it','[{"senseId":"ground_level_1","meaning":"at or near the level of the ground, rather than high above it","acceptedParaphrases":["taken from low down","shot from a low position"],"masteryContexts":[{"contextId":"u5_17_ground_level_meaning","text":"The ground-level view of the market shows the crowds, the colourful stalls and the faces of the sellers.","meaning":"seen from a low standing position, not from above","wrongMeanings":["seen from a high tower, not from the street","seen from a moving boat, not from the pavement","seen from a distant hill, not from the market"]},{"contextId":"u5_17_ground_level_paraphrase","text":"Drone footage shows the whole island, while ground-level photographs show the details that visitors notice when they walk along the beach.","meaning":"taken from a low position near the earth","wrongMeanings":["taken from the top of a tall building","taken by a camera carried on an aircraft","taken at night with a very bright flash"]}],"situationDistractors":["The helicopter rose above the valley, and the passengers photographed the river from the air.","A drone flew over the lake and filmed the island from high above the trees.","The tourists climbed to the top of the tower and looked down at the roofs of the old town.","The backpackers shared a dormitory and cooked pasta in the hostel kitchen.","A courier delivered the festival tickets to the hotel before breakfast.","The old ferry made three crossings a day, even in bad weather."],"gapDistractors":[{"contextId":"u5_17_ground_level_gap_1","answer":"ground-level","wrong":["aerial","satellite","infrared"]},{"contextId":"u5_17_ground_level_gap_2","answer":"ground-level","wrong":["aerial","distant","satellite"]},{"contextId":"u5_17_ground_level_gap_3","answer":"ground-level","wrong":["aerial","overhead","elevated"]}],"spellingErrors":["ground-levle","grownd-level","ground-leval","groud-level","ground-lavel","ground-lvel"],"masteryPassages":[{"passageId":"u5_17_ground_level_passage_1","contextId":"u5_17_ground_level_gap_1","text":"The tourist board wanted photographs that showed the old harbour as a visitor would experience it. The photographer therefore left the drone at the hotel and took only ____ pictures, crouching on the stones and looking up at the boats.","answer":"ground-level"},{"passageId":"u5_17_ground_level_passage_2","contextId":"u5_17_ground_level_gap_2","text":"Aerial pictures of the temple show its shape, but they cannot show the carvings on its walls. For those details, the guidebook uses ____ photographs taken by people standing at the foot of each wall.","answer":"ground-level"}],"contextDependentParaphrases":[],"wrongParaphrases":["taken from a boat","taken from above","taken at night"],"misleadingDistractors":["covering the whole surface of the earth","taken from a high place such as a hill or tower","showing only plants and soil"]}]'::jsonb,'[]'::jsonb,'["ground-level view","ground-level shot","ground-level photography"]'::jsonb,'live'),
('vocab_angle_of_view','angle of view','noun','the width of the scene that a camera lens can capture','[{"senseId":"angle_of_view_1","meaning":"the width of the scene that a camera lens can capture","acceptedParaphrases":["field of vision","width of the scene captured"],"masteryContexts":[{"contextId":"u5_18_angle_of_view_meaning","text":"With a narrow angle of view, the lens shows only the statue’s face, not the square around it.","meaning":"the width of the scene that a camera lens can capture","wrongMeanings":["the position of the camera above the statue","the distance from the camera to the square","the speed at which a camera lens can focus"]},{"contextId":"u5_18_angle_of_view_paraphrase","text":"Guides at the viewpoint explain that a smartphone has a wider angle of view than a telephoto lens, so it can capture more of the valley.","meaning":"how much of a scene a lens can include","wrongMeanings":["how far away from a scene a lens can focus","how quickly a lens can take a picture","how many pictures a lens can store"]}],"situationDistractors":["The photographer cleaned the lens with a soft cloth and put the camera back in its bag.","A tour guide held up a map and pointed to the route that the coach would follow.","The visitor bought a memory card and a spare battery at the airport shop.","The tourists asked the waiter whether the soup contained nuts.","The summer school offers lessons in the mornings and sports in the afternoons.","Passengers boarded the night train and found their sleeping compartments."],"gapDistractors":[{"contextId":"u5_18_angle_of_view_gap_1","answer":"angle of view","wrong":["shutter speed","battery life","memory capacity"]},{"contextId":"u5_18_angle_of_view_gap_2","answer":"angle of view","wrong":["price","weight","colour"]},{"contextId":"u5_18_angle_of_view_gap_3","answer":"angle of view","wrong":["aperture","altitude","exposure"]}],"spellingErrors":["angel of view","angle of veiw","angle off view","angl of view","angle of vew","angle of viw"],"masteryPassages":[{"passageId":"u5_18_angle_of_view_passage_1","contextId":"u5_18_angle_of_view_gap_1","text":"From the viewing platform, a phone camera cannot capture both cliffs and the waterfall between them. A lens with a wider ____ would solve the problem, because it fits more of the scene into the frame.","answer":"angle of view"},{"passageId":"u5_18_angle_of_view_passage_2","contextId":"u5_18_angle_of_view_gap_2","text":"Two photographers stood side by side at the same viewpoint. The first used a long lens and photographed only the tower; the second used a short lens, and her ____ was so wide that the tower, the bridge and the river all appeared in one picture.","answer":"angle of view"}],"contextDependentParaphrases":[],"wrongParaphrases":["speed of the shutter","weight of the lens","length of the journey"],"misleadingDistractors":["the tilt of the camera above the ground","the distance between a photographer and a subject","the number of pictures a camera can store"]}]'::jsonb,'[]'::jsonb,'["wide angle of view","narrow angle of view","increase the angle of view"]'::jsonb,'live'),
('vocab_ecological_habitats','ecological habitats','noun','natural environments where particular plants and animals live and depend on one another','[{"senseId":"ecological_habitats_1","meaning":"natural environments where particular plants and animals live and depend on one another","acceptedParaphrases":["natural homes of wildlife","environments that support living things"],"masteryContexts":[{"contextId":"u5_19_ecological_habitats_meaning","text":"The nature reserve protects several ecological habitats, including a salt marsh, a pine forest and a freshwater lake.","meaning":"natural environments where plants and animals live together","wrongMeanings":["areas of land that farmers use to grow crops","buildings where scientists study plants and animals","places where tourists can feed wild animals"]},{"contextId":"u5_19_ecological_habitats_paraphrase","text":"Rangers explain to visitors that walking off the path can harm the ecological habitats of insects and small plants.","meaning":"the natural homes of plants and animals","wrongMeanings":["the food eaten by plants and animals","the paths used by walkers and rangers","the colours of plants and animals"]}],"situationDistractors":["The hotel installed solar panels on its roof and a new heating system in the basement.","Visitors paid an entrance fee at the gate and collected a map of the gardens.","The coach company changed the departure time because of road works.","The hotel offers a free breakfast to guests who book three nights or more.","The queue for the museum shop was long, so the visitors went to the café instead.","The travel agent printed the itinerary and the boarding passes for the family."],"gapDistractors":[{"contextId":"u5_19_ecological_habitats_gap_1","answer":"ecological habitats","wrong":["shopping centres","sports stadiums","industrial parks"]},{"contextId":"u5_19_ecological_habitats_gap_2","answer":"ecological habitats","wrong":["fishing licences","tourist leaflets","holiday prices"]},{"contextId":"u5_19_ecological_habitats_gap_3","answer":"ecological habitats","wrong":["souvenir shops","hotel rooms","bus routes"]}],"spellingErrors":["ecologicle habitats","ecological habbitats","ecologial habitats","ecolagical habitats","ecological habitates","ecoligical habitats"],"masteryPassages":[{"passageId":"u5_19_ecological_habitats_passage_1","contextId":"u5_19_ecological_habitats_gap_1","text":"The island is small, but it contains a coral reef, a mangrove forest and a quiet lagoon. Scientists call these different ____ because each one provides a home for its own community of plants and animals.","answer":"ecological habitats"},{"passageId":"u5_19_ecological_habitats_passage_2","contextId":"u5_19_ecological_habitats_gap_2","text":"Tour operators are now asked to keep boats away from nesting areas and to keep visitors on marked paths. The new rules aim to protect the ____ of the birds and animals that live in the national park.","answer":"ecological habitats"}],"contextDependentParaphrases":[],"wrongParaphrases":["wildlife photographs","national parks","weather patterns"],"misleadingDistractors":["places where tourists stay close to nature","the study of how nature changes the weather","farms where animals are raised for food"]}]'::jsonb,'[]'::jsonb,'["protect ecological habitats","fragile ecological habitats","destroy ecological habitats"]'::jsonb,'live'),
('vocab_marine_world','marine world','noun','the sea and the plants and animals that live in it','[{"senseId":"marine_world_1","meaning":"the sea and the plants and animals that live in it","acceptedParaphrases":["life beneath the waves","the ocean and its creatures"],"masteryContexts":[{"contextId":"u5_20_marine_world_meaning","text":"The new aquarium lets children walk through a glass tunnel and see the marine world at close range.","meaning":"the sea and the animals and plants that live in it","wrongMeanings":["the ships and harbours that tourists visit by the sea","the beaches and cliffs that tourists photograph by the sea","the hotels and cafés that tourists use by the sea"]},{"contextId":"u5_20_marine_world_paraphrase","text":"Divers returned from the expedition with new photographs of the marine world around the remote island.","meaning":"the underwater environment and its living things","wrongMeanings":["the coastline and the towns built along it","the boats and equipment that divers use","the rules and laws that protect the shore"]}],"situationDistractors":["The coach driver turned up the heating while the passengers slept in their seats.","A group of walkers followed the path through the pine forest and stopped to eat lunch.","Visitors sat on the terrace and watched the sun go down behind the hills.","The conference delegates collected their badges and walked into the main hall.","The tourists argued about whether to take a taxi or wait for the next bus.","The airline allowed each passenger one small bag and one suitcase."],"gapDistractors":[{"contextId":"u5_20_marine_world_gap_1","answer":"marine world","wrong":["insect kingdom","desert landscape","mountain region"]},{"contextId":"u5_20_marine_world_gap_2","answer":"marine world","wrong":["city centre","farming year","royal court"]},{"contextId":"u5_20_marine_world_gap_3","answer":"marine world","wrong":["mountain forests","city parks","desert plants"]}],"spellingErrors":["marin world","marine wolrd","mareine world","marrine world","marine word","marinne world"],"masteryPassages":[{"passageId":"u5_20_marine_world_passage_1","contextId":"u5_20_marine_world_gap_1","text":"A glass-bottomed boat leaves the harbour every morning. Passengers lean over the side to see coral, shoals of fish and even a turtle, and for many of them it is their first glimpse of the ____.","answer":"marine world"},{"passageId":"u5_20_marine_world_passage_2","contextId":"u5_20_marine_world_gap_2","text":"The museum’s newest hall is filled with blue light and the sound of waves. Models of whales, sharks and jellyfish hang from the ceiling, giving visitors a feel for the ____ without getting wet.","answer":"marine world"}],"contextDependentParaphrases":[],"wrongParaphrases":["life along the coast","travel across the sea","work on a fishing boat"],"misleadingDistractors":["the ships and boats that travel on the sea","the sailors and fishermen who work at sea","the coastline and beaches next to the sea"]}]'::jsonb,'[]'::jsonb,'["explore the marine world","wonders of the marine world","protect the marine world"]'::jsonb,'live')
insert into public.vocabulary_unit_occurrences
(occurrence_id,vocabulary_id,unit_number,unit_title,set_number,position_in_unit,sense_id,status,active)
values
